import type { Locale } from '@stampa/shared';

/**
 * The embedded, versioned city dataset (generated by scripts/cities).
 * Loaded synchronously from the JS bundle: no network is needed on first launch.
 */

export type City = {
  /** GeoNames id; identical to cities.id in the database. */
  id: number;
  nameTr: string;
  nameEn: string;
  country: string;
  admin1: string | null;
  lat: number;
  lon: number;
  population: number;
  isCapital: boolean;
  /** Licence-plate code for Turkish provinces. */
  plate: string | null;
};

export type Country = {
  iso2: string;
  nameTr: string;
  nameEn: string;
  cityCount: number;
  /** ISO2 of the map polygon that draws this country. */
  geomRef: string | null;
  /** [west, south, east, north] */
  bbox: [number, number, number, number];
};

type CityBundle = {
  schema: number;
  dataVersion: string;
  count: number;
  id: number[];
  nameTr: string[];
  nameEn: string[];
  country: string[];
  admin1Names: string[];
  admin1: number[];
  lat: number[];
  lon: number[];
  population: number[];
  capitals: number[];
  plates: Record<string, string>;
};

type CountryBundle = { schema: number; countries: Country[] };

const cityBundle = require('../../assets/data/cities.v1.json') as CityBundle;
const countryBundle = require('../../assets/data/countries.v1.json') as CountryBundle;

export const dataVersion = cityBundle.dataVersion;

function inflate(b: CityBundle): City[] {
  const capitals = new Set(b.capitals);
  const out: City[] = new Array(b.count);
  for (let i = 0; i < b.count; i++) {
    const id = b.id[i]!;
    const nameTr = b.nameTr[i]!;
    out[i] = {
      id,
      nameTr,
      nameEn: b.nameEn[i] || nameTr,
      country: b.country[i]!,
      admin1: b.admin1Names[b.admin1[i]!] || null,
      lat: b.lat[i]!,
      lon: b.lon[i]!,
      population: b.population[i]!,
      isCapital: capitals.has(id),
      plate: b.plates[String(id)] ?? null,
    };
  }
  return out;
}

export const cities: City[] = inflate(cityBundle);
export const countries: Country[] = countryBundle.countries;
export const totalCities = cities.length;

export const cityById = new Map<number, City>(cities.map((c) => [c.id, c]));
export const countryByIso = new Map<string, Country>(countries.map((c) => [c.iso2, c]));

export const citiesByCountry = new Map<string, City[]>();
for (const city of cities) {
  const list = citiesByCountry.get(city.country);
  if (list) list.push(city);
  else citiesByCountry.set(city.country, [city]);
}

export function cityName(city: City, locale: Locale): string {
  return locale === 'tr' ? city.nameTr : city.nameEn;
}

export function countryName(country: Country | undefined, locale: Locale): string {
  if (!country) return '';
  return locale === 'tr' ? country.nameTr : country.nameEn;
}

/** Sorts by display name with the right collation ("Çorum" after "Bursa" in Turkish). */
export function byName<T>(locale: Locale, name: (item: T) => string) {
  return (a: T, b: T) => name(a).localeCompare(name(b), locale);
}
